    @property
    def clientApplications(self):
        return SomList(self.doc, f"{self.path}/CLIAPP-CLIE-LST", lambda d, p: ClientApplicationEntry(d, p), pattern="CLIAPP-CLIE-xxx")

    # Web browser requirements.
    @property
    def browserRequirements(self):
        return SomList(self.doc, f"{self.path}/BROREQ-BROW-LST", lambda d, p: BrowserRequirementEntry(d, p), pattern="BROREQ-BROW-xxx")

    # Desktop operating system requirements.
    @property
    def desktopOsRequirements(self):
        return SomList(self.doc, f"{self.path}/DEOSRE-DESK-LST", lambda d, p: DesktopOsRequirementEntry(d, p), pattern="DEOSRE-DESK-xxx")

    # Mobile device requirements.
    @property
    def mobileRequirements(self):
        return SomList(self.doc, f"{self.path}/MODERE-MOBI-LST", lambda d, p: MobileDeviceRequirementEntry(d, p), pattern="MODERE-MOBI-xxx")

    # Display and screen requirements.
    @property
    def displayRequirements(self):
        return DisplayRequirements(self.doc, f"{self.path}/displayRequirements")

    # Client network requirements.
    @property
    def networkRequirements(self):
        return ClientNetworkRequirements(self.doc, f"{self.path}/networkRequirements")

    # Client hardware requirements.
    @property
    def hardwareRequirements(self):
        return ClientHardwareRequirements(self.doc, f"{self.path}/hardwareRequirements")

    # Accessibility requirements for clients.
    @property
    def accessibilityRequirements(self):
        return ClientAccessibilityRequirements(self.doc, f"{self.path}/accessibilityRequirements")

    # Progressive Web App (PWA) requirements.
