    @property
    def routes(self):
        return SomList(self.doc, f"{self.path}/SCRTEN-ROUT-LST", lambda d, p: ScreenRouteEntry(d, p), pattern="SCRTEN-ROUT-xxx")

    # Contains 0+× FormScreenAssignmentEntry.
